commands.command:
cat <<'EOF' | sudo tee /etc/nginx/sites-available/node2-tls.conf
server {
    listen 8443 ssl;
    server_name node2;

    ssl_certificate     /etc/nginx/ssl/node2.fullchain.pem;
    ssl_certificate_key /etc/nginx/ssl/node2.key.pem;
    ssl_protocols       TLSv1.2;

    location / {
        root /var/www/html;
        index index.html;
    }
}
EOF
sudo ln -sf /etc/nginx/sites-available/node2-tls.conf /etc/nginx/sites-enabled/node2-tls.conf
sudo nginx -t

